import json

def block(btype, text):
    return {"type": btype, btype: {"rich_text": [{"type": "text", "text": {"content": str(text)[:1900]}}]}}

def heading(text):
    return block("heading_2", text)

def paragraph(text):
    return block("paragraph", text)

def bullet(text):
    return block("bulleted_list_item", text)

ALLOWED_TYPES = {"heading_1", "heading_2", "heading_3", "paragraph", "bulleted_list_item", "numbered_list_item", "quote", "to_do"}

claude_raw = (input.get("claude_json") or "").strip()
if claude_raw.startswith("```"):
    claude_raw = claude_raw.strip("`")
    if claude_raw[:4].lower() == "json":
        claude_raw = claude_raw[4:]
    claude_raw = claude_raw.strip()

try:
    parsed = json.loads(claude_raw)
except Exception:
    parsed = None

if parsed is None:
    jd_blocks_raw = []
    changes_made = ["(JD generation failed — check manually)"]
    incoherencies = ["(JD generation failed — check manually)"]
else:
    jd_blocks_raw = parsed.get("jd_blocks") or []
    changes_made = parsed.get("changes_made") or ["No significant changes made"]
    incoherencies = parsed.get("incoherencies") or ["None identified"]

jd_blocks = []
for b in jd_blocks_raw:
    btype = b.get("type") if isinstance(b, dict) else None
    text = b.get("text") if isinstance(b, dict) else None
    if btype in ALLOWED_TYPES and text:
        jd_blocks.append(block(btype, text))

if not jd_blocks:
    jd_blocks = [paragraph("(job description generation failed — check manually)")]

blocks = [heading("Job description")]
blocks += jd_blocks
blocks.append(heading("What has been changed"))
blocks += [bullet(c) for c in changes_made]
blocks.append(heading("Watch out — possible incoherencies"))
blocks += [bullet(i) for i in incoherencies]

blocks = blocks[:100]

result = {"children_json": json.dumps({"children": blocks})}

return result
